import{openAuditPage,pause}from'/workspace/trading101/docs/adsense-2026-10-22/browser-session.mjs';import{mkdirSync,writeFileSync}from'node:fs';
const[sha,origin,stage]=process.argv.slice(2),root='/workspace/trading101/docs/adsense-2026-10-22/evidence/',folder=root+'audio-control-'+stage+'-20261030';mkdirSync(folder,{recursive:true});const p=await openAuditPage('about:blank',9258),rows=[];
for(const width of[360,1280]){await p.send('Emulation.setDeviceMetricsOverride',{width,height:800,deviceScaleFactor:1,mobile:width<500});await p.send('Page.navigate',{url:origin+'/trader/muzh3q'});await p.wait("!!document.querySelector('button[aria-label=\"Play background music\"]') && !!document.querySelector('main h1')");await p.evaluate('document.fonts.ready.then(()=>true)',true);await p.evaluate("[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reject analytics')?.click();true");for(const theme of['light','dark']){await p.evaluate(`if(document.documentElement.classList.contains('light')!==${theme==='light'})[...document.querySelectorAll('button[aria-label*=theme]')].find(b=>b.getClientRects().length).click();true`);for(const position of['top','footer']){await p.evaluate(position==='top'?'scrollTo(0,0);true':'scrollTo(0,document.documentElement.scrollHeight);true');await pause(350);const info=await p.evaluate(`(()=>{const b=document.querySelector('button[aria-label="Play background music"]'),s=getComputedStyle(b),r=b.getBoundingClientRect();const under=document.elementsFromPoint(r.left+r.width/2,r.top+r.height/2).filter(e=>!b.contains(e)&&e!==b).map(e=>({tag:e.tagName,background:getComputedStyle(e).backgroundColor}));return{color:s.color,background:s.backgroundColor,border:s.borderColor,opacity:s.opacity,under,theme:document.documentElement.classList.contains('light')?'light':'dark'}})()`);const screenshot=width+'-'+theme+'-'+position+'.png';await p.screenshot(folder+'/'+screenshot);rows.push({width,theme,position,...info,screenshot});}}}
